const REQUIRED_BASE_KEYS = ["id", "createdAt", "updatedAt", "status", "source"];

export function validateCollection(collection) {
  const errors = [];
  const seenIds = new Set();
  for (const item of collection.items || []) {
    for (const key of REQUIRED_BASE_KEYS) {
      if (!item[key]) errors.push(`Missing ${key} on ${item.id || "record"}`);
    }
    if (item.id && seenIds.has(item.id)) {
      errors.push(`Duplicate ID detected: ${item.id}`);
    }
    if (item.id) seenIds.add(item.id);
  }
  return { valid: errors.length === 0, errors };
}
